from concurrent import futures
import grpc,hashlib,json,threading
import kv_store_pb2 as pb, kv_store_pb2_grpc as rpc
LOCK=threading.Lock(); STATE='/app/quota-state.json'; AUTH='/app/auth-registry.json'
def allowed(ctx,scope):
 meta=dict(ctx.invocation_metadata()); token=meta.get('authorization','').removeprefix('Bearer ')
 h=hashlib.sha256(token.encode()).hexdigest()
 rows=json.load(open(AUTH))['credentials']
 return any(r['active'] and r['sha256']==h and r['scope'] in (scope,'bootstrap') for r in rows)
class Server(rpc.KVStoreServicer):
 def GetVal(self,req,ctx):
  if not allowed(ctx,'read'): ctx.abort(grpc.StatusCode.PERMISSION_DENIED,'denied')
  return pb.GetValResponse(val=json.load(open(STATE)).get(req.key,0))
 def SetVal(self,req,ctx):
  if not allowed(ctx,'write'): ctx.abort(grpc.StatusCode.PERMISSION_DENIED,'denied')
  with LOCK:
   d=json.load(open(STATE)); d[req.key]=req.value; open(STATE,'w').write(json.dumps(d,indent=2)+'\n')
  return pb.SetValResponse(val=req.value)
s=grpc.server(futures.ThreadPoolExecutor(max_workers=4)); rpc.add_KVStoreServicer_to_server(Server(),s); s.add_insecure_port('127.0.0.1:5328'); s.start(); open('/app/kv.pid','w').write(str(__import__('os').getpid())); s.wait_for_termination()
